from AlgorithmImports import *
import math


class CrossAndStreakStrategy(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)

        self.symbols = {}
        for ticker in ["SPY", "AAPL", "IBM", "BAC", "AIG"]:
            self.symbols[ticker] = self.AddEquity(ticker, Resolution.Daily).Symbol

        self.spy = self.symbols["SPY"]
        self.aapl = self.symbols["AAPL"]

        self.spy_sma = SimpleMovingAverage(100)
        self.aapl_rsi = RelativeStrengthIndex(14, MovingAverageType.Wilders)

        self.spy_previous_sma = None
        self.spy_previous_close = None
        self.aapl_red_streak = 0
        self.aapl_previous_rsi = None

        self.spy_lot = 0
        self.aapl_lot = 0
        self.pending_orders = {}

        self.spy_history_ready = False
        self.aapl_history_ready = False

        self.SetWarmUp(100, Resolution.Daily)

    def OnData(self, data):
        required = [self.spy, self.aapl,
                    self.symbols["IBM"], self.symbols["BAC"], self.symbols["AIG"]]

        if any(not data.ContainsKey(symbol) or data[symbol] is None
               for symbol in required):
            return

        spy_bar = data[self.spy]
        aapl_bar = data[self.aapl]

        self.spy_sma.Update(spy_bar.EndTime, spy_bar.Close)
        self.aapl_rsi.Update(aapl_bar.EndTime, aapl_bar.Close)

        if self.spy_previous_close is None:
            self.spy_previous_close = spy_bar.Close
            self.spy_previous_sma = self.spy_sma.Current.Value if self.spy_sma.IsReady else None
            self.aapl_previous_rsi = self.aapl_rsi.Current.Value if self.aapl_rsi.IsReady else None
            return

        if aapl_bar.Close < self.aapl_previous_close:
            self.aapl_red_streak += 1
        else:
            self.aapl_red_streak = 0

        if self.spy_sma.IsReady:
            self.spy_history_ready = True

        if self.aapl_rsi.IsReady:
            self.aapl_history_ready = True

        if self.IsWarmingUp:
            self.spy_previous_close = spy_bar.Close
            if self.spy_sma.IsReady:
                self.spy_previous_sma = self.spy_sma.Current.Value
            if self.aapl_rsi.IsReady:
                self.aapl_previous_rsi = self.aapl_rsi.Current.Value
            return

        spy_sma_value = self.spy_sma.Current.Value
        aapl_rsi_value = self.aapl_rsi.Current.Value

        if self.spy_lot > 0 and self.spy_previous_sma is not None:
            spy_sell = (
                self.spy_previous_close <= self.spy_previous_sma and
                spy_bar.Close > 0 and
                spy_bar.Close < spy_sma_value
            )
            if spy_sell:
                self.SubmitLiquidation("SPY", self.spy, self.spy_lot)

        if self.aapl_lot > 0 and self.aapl_history_ready:
            if aapl_rsi_value > 60:
                self.SubmitLiquidation("AAPL", self.aapl, self.aapl_lot)

        if self.spy_lot == 0 and "SPY" not in self.pending_orders and self.spy_history_ready:
            spy_buy = (
                self.spy_previous_close <= self.spy_previous_sma and
                spy_bar.Close > spy_sma_value
            )
            if spy_buy:
                target_value = 0.40 * self.Portfolio.TotalPortfolioValue
                quantity = int(math.floor(target_value / spy_bar.Close))
                if quantity > 0:
                    ticket = self.MarketOrder(self.spy, quantity, tag="Strategy A Buy")
                    self.pending_orders[ticket.OrderId] = ("SPY", quantity, "buy")

        if self.aapl_lot == 0 and "AAPL" not in self.pending_orders and self.aapl_history_ready:
            if self.aapl_red_streak >= 3:
                if self.Portfolio.Cash >= 20000:
                    quantity = int(math.floor(20000 / aapl_bar.Close))
                    if quantity > 0:
                        ticket = self.MarketOrder(self.aapl, quantity, tag="Strategy B Buy")
                        self.pending_orders[ticket.OrderId] = ("AAPL", quantity, "buy")

        self.spy_previous_close = spy_bar.Close
        self.spy_previous_sma = spy_sma_value
        self.aapl_previous_close = aapl_bar.Close
        self.aapl_previous_rsi = aapl_rsi_value

    def SubmitLiquidation(self, name, symbol, quantity):
        if name in self.pending_orders:
            return

        ticket = self.MarketOrder(symbol, -quantity, tag=f"{name} Sell")
        self.pending_orders[ticket.OrderId] = (name, quantity, "sell")

    def OnOrderEvent(self, orderEvent):
        order_id = orderEvent.OrderId

        if order_id not in self.pending_orders:
            return

        name, quantity, action = self.pending_orders[order_id]

        if orderEvent.Status == OrderStatus.Filled:
            if name == "SPY":
                self.spy_lot = quantity if action == "buy" else 0
            elif name == "AAPL":
                self.aapl_lot = quantity if action == "buy" else 0

            del self.pending_orders[order_id]

        elif orderEvent.Status in [
            OrderStatus.Canceled,
            OrderStatus.Invalid,
            OrderStatus.PartiallyFilled
        ]:
            if orderEvent.Status in [OrderStatus.Canceled, OrderStatus.Invalid]:
                del self.pending_orders[order_id]
