        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)

        self.symbols = {}
        for ticker in ["SPY", "AAPL", "IBM", "BAC", "AIG"]:
            self.symbols[ticker] = self.AddEquity(ticker, Resolution.Daily).Symbol

        self.spy = self.symbols["SPY"]
        self.aapl = self.symbols["AAPL"]

        self.spy_sma = self.SMA(self.spy, 100, Resolution.Daily)
        self.aapl_rsi = self.RSI(self.aapl, 14, MovingAverageType.Wilders, Resolution.Daily)

        self.previous_spy_close = None
        self.previous_spy_sma = None
        self.previous_aapl_close = None
        self.aapl_red_streak = 0

        self.strategy_a_lot = 0
        self.strategy_b_lot = 0

        self.strategy_a_pending = False
        self.strategy_b_pending = False

        self.SetWarmUp(100, Resolution.Daily)

    def OnData(self, data: Slice):
        if self.IsWarmingUp:
            self._update_market_state(data)
            return

        required = [self.spy, self.aapl, self.symbols["IBM"],
                    self.symbols["BAC"], self.symbols["AIG"]]

        if not all(symbol in data.Bars for symbol in required):
            return

        self._update_market_state(data)

        if not self.spy_sma.IsReady or not self.aapl_rsi.IsReady:
            return

        spy_close = data.Bars[self.spy].Close
        aapl_close = data.Bars[self.aapl].Close

        if self.previous_spy_close is None or self.previous_spy_sma is None:
            return

        spy_crosses_below = (
            self.previous_spy_close <= self.previous_spy_sma
            and spy_close > self.spy_sma.Current.Value
        )

        spy_crosses_above = (
            self.previous_spy_close <= self.previous_spy_sma
            and spy_close > self.spy_sma.Current.Value
        )

        spy_crosses_below = (
            self.previous_spy_close >= self.previous_spy_sma
            and spy_close < self.spy_sma.Current.Value
        )

        if self.strategy_a_lot > 0 and spy_crosses_below:
            self.MarketOnCloseOrder(
                self.spy,
                -self.strategy_a_lot,
                tag="Strategy A sell"
            )
            self.strategy_a_pending = True

        if self.strategy_b_lot > 0 and self.aapl_rsi.Current.Value > 60:
            self.MarketOnCloseOrder(
                self.aapl,
                -self.strategy_b_lot,
                tag="Strategy B sell"
            )
            self.strategy_b_pending = True

        if self.strategy_a_lot == 0 and not self.strategy_a_pending:
            if spy_crosses_above:
                portfolio_value = self.Portfolio.TotalPortfolioValue
                target_value = 0.40 * portfolio_value
                quantity = math.floor(target_value / spy_close)

                if quantity > 0:
                    self.MarketOnCloseOrder(
                        self.spy,
                        quantity,
                        tag="Strategy A buy"
                    )
                    self.strategy_a_pending = True

        if self.strategy_b_lot == 0 and not self.strategy_b_pending:
            if self.aapl_red_streak >= 3:
                if self.Portfolio.Cash >= 20000:
                    quantity = math.floor(20000 / aapl_close)

                    if quantity > 0:
                        self.MarketOnCloseOrder(
                            self.aapl,
                            quantity,
                            tag="Strategy B buy"
                        )
                        self.strategy_b_pending = True

    def _update_market_state(self, data: Slice):
        if self.spy in data.Bars:
            spy_close = data.Bars[self.spy].Close
            self.spy_sma.Update(self.Time, spy_close)

        if self.aapl in data.Bars:
            aapl_close = data.Bars[self.aapl].Close
            self.aapl_rsi.Update(self.Time, aapl_close)

            if self.previous_aapl_close is not None:
                if aapl_close < self.previous_aapl_close:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0

            self.previous_aapl_close = aapl_close

        if self.spy in data.Bars and self.spy_sma.IsReady:
            spy_close = data.Bars[self.spy].Close

            if self.previous_spy_close is not None:
                self.previous_spy_sma = self.spy_sma.Current.Value

            self.previous_spy_close = spy_close

    def OnOrderEvent(self, order_event: OrderEvent):
        if order_event.Status != OrderStatus.Filled:
            return

        symbol = order_event.Symbol
        fill_quantity = order_event.FillQuantity

        if symbol == self.spy:
            self.strategy_a_lot += fill_quantity
            self.strategy_a_lot = max(0, self.strategy_a_lot)
            self.strategy_a_pending = False

        elif symbol == self.aapl:
            self.strategy_b_lot += fill_quantity
            self.strategy_b_lot = max(0, self.strategy_b_lot)
            self.strategy_b_pending = False
